import{_ as n,y as i,a as d,o as l,a2 as a,D as r,g as t,I as o}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"Section Types","description":"","frontmatter":{},"headers":[],"relativePath":"appearance/section-types.md","filePath":"appearance/section-types.md","lastUpdated":1789441803000}'),h={name:"appearance/section-types.md"};function p(c,e,g,u,m,f){const s=i("ImagePopup");return l(),d("div",null,[e[0]||(e[0]=a('<h1 id="section-types" tabindex="-1">Section Types <a class="header-anchor" href="#section-types" aria-label="Permalink to &quot;Section Types&quot;">​</a></h1><p>A section is one block of your storefront: a banner slideshow, a strip of products, a block of your own content and so on. This page lists the fields of each built-in type. You edit them in the section editor, under <strong>Appearance &gt;&gt; Themes</strong>; see <a href="./themes.html#edit-a-section">Edit a section</a>.</p><table tabindex="0"><thead><tr><th>Type</th><th>What it shows</th><th>Where it appears</th></tr></thead><tbody><tr><td><a href="#image-carousel">Image Carousel</a></td><td>A slideshow of banner images</td><td>Home page</td></tr><tr><td><a href="#product-carousel">Product Carousel</a></td><td>A strip of products chosen by filters</td><td>Home page</td></tr><tr><td><a href="#category-carousel">Category Carousel</a></td><td>A strip of categories</td><td>Home page</td></tr><tr><td><a href="#static-content">Static Content</a></td><td>Your own HTML and CSS</td><td>Home page</td></tr><tr><td><a href="#services-content">Services Content</a></td><td>Short service promises, such as free shipping</td><td>Most pages, but not sign-in, cart, checkout, search results or account pages</td></tr><tr><td><a href="#footer-links">Footer Links</a></td><td>Columns of links in the footer</td><td>Most pages, but not sign-in, cart or checkout pages</td></tr></tbody></table><p>Changes to fields, switching sections on or off and their order are held until you click <strong>Publish</strong> in the section editor. See <a href="./themes.html#most-changes-wait-until-you-publish">Most changes wait until you publish</a>.</p><h2 id="image-carousel" tabindex="-1">Image Carousel <a class="header-anchor" href="#image-carousel" aria-label="Permalink to &quot;Image Carousel&quot;">​</a></h2><p>The banner slideshow at the top of your home page. Click <strong>Add Slider</strong> to add a slide. Each slide has these fields:</p><p><strong>Slider Image:</strong> The banner itself. Click <strong>Image</strong> to upload a JPG, PNG, WebP or BMP image of up to 50 MB. It&#39;s saved in WebP format. A size of 1920 × 700 pixels suits the default theme.</p><p><strong>Image Title:</strong> A short description of the image, used by screen readers and search engines. It isn&#39;t shown on the slide.</p><p><strong>Link:</strong> Where a shopper who clicks the slide goes. Enter a path on your store, such as a category&#39;s URL key, or a full web address.</p><p>Slides are numbered in the order they play. Drag a slide by its handle to move it, or click the bin icon to remove it.</p>',10)),r(s,{src:"/images/appearance/image-carousel.png",alt:"Image Carousel fields with numbered slides, each with a Slider Image, an Image Title and a Link"}),e[1]||(e[1]=a('<h2 id="product-carousel" tabindex="-1">Product Carousel <a class="header-anchor" href="#product-carousel" aria-label="Permalink to &quot;Product Carousel&quot;">​</a></h2><p>A titled strip of products, such as <strong>Mens Collection</strong>.</p><p><strong>Title:</strong> The heading shown above the strip.</p><p><strong>Filters:</strong> Which products appear, and in what order. Click <strong>Add Filter</strong>, choose a filter on the left and its value on the right. Remove a filter with the bin icon.</p><table tabindex="0"><thead><tr><th>Filter</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Sort</strong></td><td>The order of the products, using the sort options of your storefront, such as <strong>Newest First</strong> or <strong>Cheapest First</strong></td></tr><tr><td><strong>Limit</strong></td><td>How many products the strip holds. The choices are the numbers in <strong>Products Per Page</strong>, in the <strong>Storefront</strong> section of <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>, or 12, 24, 36 and 48 when that setting is empty.</td></tr><tr><td><strong>Category ID</strong></td><td>Shows products from one category. Categories are listed by their full path, so two with the same name can be told apart.</td></tr><tr><td><strong>Featured</strong></td><td><strong>Yes</strong> shows only featured products</td></tr><tr><td><strong>New</strong></td><td><strong>Yes</strong> shows only products marked as new</td></tr></tbody></table><p>Once every filter is in use, <strong>Add Filter</strong> is greyed out. Hover over it to see &quot;Every available filter has already been added.&quot;</p>',6)),r(s,{src:"/images/appearance/product-carousel.png",alt:"Product Carousel fields with a title and Sort, Limit and Category ID filters"}),e[2]||(e[2]=a('<h2 id="category-carousel" tabindex="-1">Category Carousel <a class="header-anchor" href="#category-carousel" aria-label="Permalink to &quot;Category Carousel&quot;">​</a></h2><p>A strip of categories, so shoppers can jump straight into a department.</p><p><strong>Filters:</strong> Which categories appear:</p><ul><li><strong>Limit</strong>: how many categories the strip holds, from the same choices as the Product Carousel. Without a limit, it shows 10.</li><li><strong>Parent ID</strong>: shows the subcategories of one or more categories. Choose <strong>Root</strong> to show your top-level categories.</li></ul><p>The panel also offers a <strong>Sort</strong> filter. Don&#39;t rely on it to order the categories; check the order in the preview.</p>',5)),r(s,{src:"/images/appearance/category-carousel.png",alt:"Category Carousel fields with Sort, Limit and Parent ID filters"}),e[3]||(e[3]=t("h2",{id:"static-content",tabindex:"-1"},[o("Static Content "),t("a",{class:"header-anchor",href:"#static-content","aria-label":'Permalink to "Static Content"'},"​")],-1)),e[4]||(e[4]=t("p",null,"A block of your own content, such as an offer banner or a promotional band between two carousels.",-1)),e[5]||(e[5]=t("p",null,[t("strong",null,"HTML:"),o(" The block's markup. Click "),t("strong",null,"Add Media"),o(" to upload an image, or an MP4, WebM or OGG video, of up to 50 MB. It's added to the markup where your cursor is. Images are saved in WebP format.")],-1)),e[6]||(e[6]=t("p",null,[t("strong",null,"CSS:"),o(" The styles for the block.")],-1)),r(s,{src:"/images/appearance/static-content.png",alt:"Static Content fields with the HTML editor, the Add Media button and the CSS editor"}),e[7]||(e[7]=a('<div class="warning custom-block"><p class="custom-block-title">Keep your styles to your block</p><p>The CSS applies to the whole page, not only to this block. Give your markup its own class and start every rule with it, for example <code>.home-offer h1 { ... }</code>. Otherwise the styles change other parts of the storefront too.</p></div><p>Scripts, frames and forms are removed from the HTML when it&#39;s saved, so a block that relies on them won&#39;t work.</p><h2 id="services-content" tabindex="-1">Services Content <a class="header-anchor" href="#services-content" aria-label="Permalink to &quot;Services Content&quot;">​</a></h2><p>The service promises shown on most storefront pages, such as free shipping or easy returns. Click <strong>Add Services</strong> to add a promise. Each one has these fields:</p><p><strong>Service Icon:</strong> The name of the icon shown beside the promise, typed as text, such as <code>icon-truck</code> for delivery.</p><p><strong>Title:</strong> The promise itself, in a few words.</p><p><strong>Description:</strong> One line of supporting detail.</p>',7)),r(s,{src:"/images/appearance/services-content.png",alt:"Services Content fields with numbered services, each with a Service Icon, a Title and a Description"}),e[8]||(e[8]=a('<h2 id="footer-links" tabindex="-1">Footer Links <a class="header-anchor" href="#footer-links" aria-label="Permalink to &quot;Footer Links&quot;">​</a></h2><p>The columns of links in your storefront footer. A channel has one <strong>Footer Links</strong> section. It&#39;s pinned to the bottom of the page, so it can&#39;t be moved or duplicated.</p><h3 id="add-a-footer-link" tabindex="-1">Add a footer link <a class="header-anchor" href="#add-a-footer-link" aria-label="Permalink to &quot;Add a footer link&quot;">​</a></h3><ol><li>Open the <strong>Footer Links</strong> section.</li><li>Under <strong>Columns</strong>, click <strong>Add Column</strong> to start a new column, or use an existing one.</li><li>In the column, click <strong>Add Link</strong>.</li><li>Enter the link&#39;s <strong>Title</strong>, the words a shopper reads.</li><li>Enter its <strong>URL</strong>, such as <code>page/about-us</code> for a CMS page.</li><li>Click <strong>Publish</strong> in the section editor.</li></ol>',4)),r(s,{src:"/images/appearance/footer-links.png",alt:"Footer Links fields with a column of links, each with a Title and a URL"}),e[9]||(e[9]=t("p",null,[o("Drag columns and links by their handles to change the order. A link needs a "),t("strong",null,"Title"),o(" to appear in the footer. Links left without a title and URL are dropped when the section is saved, and so are empty columns. The default theme shows as many columns as you add, but a theme you install may limit the number.")],-1)),e[10]||(e[10]=t("h2",{id:"types-added-by-a-theme",tabindex:"-1"},[o("Types added by a theme "),t("a",{class:"header-anchor",href:"#types-added-by-a-theme","aria-label":'Permalink to "Types added by a theme"'},"​")],-1)),e[11]||(e[11]=t("p",null,[o("The default theme offers the six types above. A theme you install can add types of its own, such as a testimonial slider or a brand strip, or offer only some of the built-in types. Its types appear under "),t("strong",null,"Type"),o(" when you create a section for that theme. They have their own fields, and you edit and publish them like the built-in types. If a type you expect is missing, check that you're customizing the theme it belongs to.")],-1))])}const T=n(h,[["render",p]]);export{b as __pageData,T as default};
